import (
	"encoding/csv"
	"encoding/json"

	history "github.com/floris3456/cliproxyapi-quota-handoff/internal/historyreports/internal/cpamp"
)

func WriteQuotaEvidence(c *csv.Writer, p history.QuotaUsageEvidence) {
	defer c.Flush()
	_ = c.Write([]string{"row_type", "evidence_json"})
	write := func(kind string, v any) { raw, _ := json.Marshal(v); _ = c.Write([]string{kind, string(raw)}) }
	write("filter", p.Filter)
	write("price_book", p.PriceBook)
	write("valuation", p.Valuation)
	write("api_value", p.Value)
	write("normalization", p.Normalization)
	write("window", p.Window)
	write("policy", p.Policy)
	write("reconciled", p.Reconciled)
	write("shared_reconciled", p.SharedReconciled)
	for _, e := range p.Events {
		write("event", e)
	}
	for _, e := range p.SharedEvents {
		write("shared_event", e)
	}
	for _, e := range p.BoundaryEvents {
		write("boundary_event", e)
	}
	for _, o := range p.Observations {
		write("observation", o)
	}
	for _, o := range p.MeterObservations {
		write("meter_observation", o)
	}
	write("captured_prices", p.Prices)
	write("models", p.Models)
	write("poll_runs", p.PollRuns)
}
